'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),{createLedger}=require('../duplicate-notification-state');
const a={conflictId:'a'.repeat(64),signature:'b'.repeat(64)};
test('dismissal and cleared history survive restart and identical reconnect scans',()=>{let disk;const create=()=>createLedger({load:()=>disk,save:value=>disk=structuredClone(value)});let l=create();l.observe([a]);l.action(a.conflictId,'dismiss');l=create();for(let i=0;i<10;i++)l.observe([a]);assert.equal(l.history().length,1);assert.equal(l.history()[0].dismissed,true);l.clearAll();l=create();l.observe([a]);assert.equal(l.history().length,0);l.observe([{...a,signature:'c'.repeat(64)}]);assert.equal(l.history().length,1);assert.equal(l.history()[0].dismissed,false);});
test('intentional same-retailer reuse stays resolved until the actual conflict changes',()=>{const l=createLedger();assert.equal(l.observe([a]).length,1);l.action(a.conflictId,'keep');assert.equal(l.observe([a]).length,0);assert.equal(l.observe([{...a,signature:'d'.repeat(64)}]).length,1);assert.equal(l.history().length,1);});
test('resolved conflicts keep a single history record and reopening never writes profiles',()=>{const l=createLedger();l.observe([a]);l.observe([]);assert.equal(l.history()[0].resolved,true);l.observe([a]);assert.equal(l.history().length,1);assert.equal(l.history()[0].resolved,false);l.action(a.conflictId,'clear');l.action(a.conflictId,'reopen');assert.equal(l.history().length,1);assert.deepEqual(Object.keys(l.history()[0]).sort(),['at','cleared','dismissed','id','kept','resolved','signature']);});
